def calculate_x_next(x_i, x_i_plus_1):
    """Calculates x_{i+2} = (x_{i+1}^2 - x_i) / (x_i + 1)"""
    numerator = x_i_plus_1**2 - x_i
    denominator = x_i + 1
    if denominator == 0:
        return None # Should not happen for positive integers
    if numerator % denominator != 0:
        return None # Not an integer
    return numerator // denominator

# Known N=3 solutions (x1, x2, x3)
solutions = [
    (1, 3, 4),
    (4, 7, 9),
    (1, 5, 12),
    (1, 7, 24)
]

results = {}

print("--- Checking N=4 extension ---")
for sol in solutions:
    x1, x2, x3 = sol
    # Calculate x4 using x2, x3 (i=2)
    x4 = calculate_x_next(x2, x3)

    if x4 is not None:
        results[sol] = {"x4": x4, "N=4_valid": True}
        print(f"Solution {sol} yields integer x4 = {x4}")

        # If x4 is integer, check x5 using x3, x4 (i=3)
        x5 = calculate_x_next(x3, x4)
        if x5 is not None:
            results[sol]["x5"] = x5
            print(f"Solution {sol} continues to N=5 with x5 = {x5}")

            # If x5 is integer, check x6 using x4, x5 (i=4)
            x6 = calculate_x_next(x4, x5)
            if x6 is not None:
                results[sol]["x6"] = x6
                print(f"Solution {sol} continues to N=6 with x6 = {x6}")
            else:
                results[sol]["N>=6_valid"] = False
        else:
            results[sol]["N>=5_valid"] = False
    else:
        results[sol] = {"x4": None, "N=4_valid": False}
        print(f"Solution {sol} does NOT yield integer x4.")

print("\n--- Summary ---")
for sol, data in results.items():
    status = "Stops at N=3"
    if data.get("N=4_valid"):
        if data.get("x5") is not None:
            if data.get("x6") is not None:
                status = "Continues to N=6"
            else:
                status = "Continues to N=5, stops at N=5"
        else:
            status = "Stops at N=3 (x4 not integer)"
    print(f"Starting sequence {sol}: {status}")
